    SELECT 1 / 0 AS boom;
END TRY
BEGIN CATCH
    THROW 50001, N'failed', 1;
END CATCH;

SELECT 1 AS anchor;
WITH n (i) AS (
    SELECT 1
    UNION ALL
    SELECT i + 1 FROM n WHERE i < 10
)
SELECT i FROM n OPTION (MAXRECURSION 100);

SELECT 1 AS anchor;
SELECT id,
       ROW_NUMBER() OVER (PARTITION BY g ORDER BY id) AS rn,
       LAG(v, 1, 0) OVER (PARTITION BY g ORDER BY id) AS prev_v,
       SUM(v) OVER (ORDER BY id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running
FROM dbo.t;

SELECT 1 AS anchor;
SELECT p.[2024], p.[2025]
FROM (SELECT y, amt FROM dbo.sales) AS s
PIVOT (SUM(amt) FOR y IN ([2024], [2025])) AS p;
SELECT u.y, u.amt FROM dbo.wide AS w UNPIVOT (amt FOR y IN ([2024], [2025])) AS u;

