DECLARE @ids TABLE (id int);
UPDATE dbo.t SET v = v + 1 OUTPUT inserted.id INTO @ids WHERE id > 0;
INSERT INTO dbo.t (v) OUTPUT inserted.id, inserted.v VALUES (1);
DELETE FROM dbo.t OUTPUT deleted.id WHERE id < 0;
